<script setup>import {computed} from 'vue';import StatCard from '../components/StatCard.vue';import ProgressRing from '../components/ProgressRing.vue';const p=defineProps({totalPoints:Number,target:Number,achievement:Number,remaining:Number,totalQty:Number,jobs:Array});const recent=computed(()=>p.jobs.slice(0,5));const daily=computed(()=>{const m={};p.jobs.forEach(j=>m[j.date]=(m[j.date]||0)+j.total);return Object.entries(m).sort((a,b)=>a[0].localeCompare(b[0])).slice(-7)});const max=computed(()=>Math.max(...daily.value.map(x=>x[1]),1))</script><template><section class="page-head"><div><span class="eyebrow">OVERVIEW</span><h1>Dashboard</h1><p>Pantau pencapaian poin berdasarkan pekerjaan yang sudah dicatat.</p></div><div class="date-chip">● Periode aktif</div></section><div class="stats-grid"><StatCard label="Total Poin" :value="totalPoints.toLocaleString('id-ID')" helper="akumulasi periode" icon="★" accent/><StatCard label="Target Poin" :value="target.toLocaleString('id-ID')" helper="target periode" icon="◎"/><StatCard label="Sisa Target" :value="remaining.toLocaleString('id-ID')" helper="poin yang dibutuhkan" icon="↗"/><StatCard label="Pekerjaan" :value="totalQty" helper="total unit pekerjaan" icon="▣"/></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><span class="eyebrow">TARGET</span><h2>Pencapaian Target</h2></div><span class="badge">{{achievement.toFixed(1)}}%</span></div><div class="progress-content"><ProgressRing :value="achievement"/><div class="progress-copy"><strong>{{totalPoints.toLocaleString('id-ID')}} <small>/ {{target.toLocaleString('id-ID')}} poin</small></strong><p>{{remaining>0?`Masih membutuhkan ${remaining.toLocaleString('id-ID')} poin untuk mencapai target.`:'Target periode telah tercapai.'}}</p><div class="bar"><i :style="{width:Math.min(achievement,100)+'%'}"></i></div></div></div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">AKTIVITAS</span><h2>Pekerjaan Terbaru</h2></div></div><div class="mini-list"><div v-for="j in recent" :key="j.id" class="mini-row"><span class="mini-date">{{j.date.slice(8,10)}}</span><div><b>{{j.master?.name}}</b><small>{{j.qty}} pekerjaan × {{j.points}} poin</small></div><strong>+{{j.total}}</strong></div><div v-if="!recent.length" class="empty">Belum ada pekerjaan.</div></div></section></div><section class="panel chart-panel"><div class="panel-head"><div><span class="eyebrow">TREND</span><h2>Poin Harian</h2></div><span class="muted">7 catatan terakhir</span></div><div class="bar-chart"><div v-for="x in daily" :key="x[0]" class="bar-col"><span>{{x[1]}}</span><i :style="{height:(x[1]/max*150)+'px'}"></i><small>{{x[0].slice(8,10)}}</small></div><div v-if="!daily.length" class="empty">Belum ada data.</div></div></section></template>